
import { Sudoku } from './sudoku_pack.js';

function buildSingleHint(x, y, value, type) {
    return { x, y, value, type };
}

function findNakedSingle(sudoku) {
    for (let y = 0; y < 9; y++) {
        for (let x = 0; x < 9; x++) {
            if (!sudoku.is_empty_pos({ x, y })) continue;

            const candidates = sudoku.numbers_to_select({ x, y });
            if (candidates.length === 1) {
                return buildSingleHint(x, y, candidates[0], 'naked-single');
            }
        }
    }

    return null;
}

function findHiddenSingleInRow(sudoku) {
    for (let y = 0; y < 9; y++) {
        const positionsByNumber = new Map();

        for (let value = 1; value <= 9; value++) {
            positionsByNumber.set(value, []);
        }

        for (let x = 0; x < 9; x++) {
            if (!sudoku.is_empty_pos({ x, y })) continue;

            const candidates = sudoku.numbers_to_select({ x, y });
            for (const value of candidates) {
                positionsByNumber.get(value).push({ x, y });
            }
        }

        for (let value = 1; value <= 9; value++) {
            const positions = positionsByNumber.get(value);
            if (positions.length === 1) {
                const pos = positions[0];
                return buildSingleHint(pos.x, pos.y, value, 'hidden-single-row');
            }
        }
    }

    return null;
}

function findHiddenSingleInColumn(sudoku) {
    for (let x = 0; x < 9; x++) {
        const positionsByNumber = new Map();

        for (let value = 1; value <= 9; value++) {
            positionsByNumber.set(value, []);
        }

        for (let y = 0; y < 9; y++) {
            if (!sudoku.is_empty_pos({ x, y })) continue;

            const candidates = sudoku.numbers_to_select({ x, y });
            for (const value of candidates) {
                positionsByNumber.get(value).push({ x, y });
            }
        }

        for (let value = 1; value <= 9; value++) {
            const positions = positionsByNumber.get(value);
            if (positions.length === 1) {
                const pos = positions[0];
                return buildSingleHint(pos.x, pos.y, value, 'hidden-single-column');
            }
        }
    }

    return null;
}

function findHiddenSingleInBox(sudoku) {
    for (let boxY = 0; boxY < 3; boxY++) {
        for (let boxX = 0; boxX < 3; boxX++) {
            const positionsByNumber = new Map();

            for (let value = 1; value <= 9; value++) {
                positionsByNumber.set(value, []);
            }

            for (let offsetY = 0; offsetY < 3; offsetY++) {
                for (let offsetX = 0; offsetX < 3; offsetX++) {
                    const x = boxX * 3 + offsetX;
                    const y = boxY * 3 + offsetY;

                    if (!sudoku.is_empty_pos({ x, y })) continue;

                    const candidates = sudoku.numbers_to_select({ x, y });
                    for (const value of candidates) {
                        positionsByNumber.get(value).push({ x, y });
                    }
                }
            }

            for (let value = 1; value <= 9; value++) {
                const positions = positionsByNumber.get(value);
                if (positions.length === 1) {
                    const pos = positions[0];
                    return buildSingleHint(pos.x, pos.y, value, 'hidden-single-box');
                }
            }
        }
    }

    return null;
}

// 纯领域 Game 类，无 UI/store 依赖
export class Game {
    #sudoku;
    #started;
    #history;
    #currentIndex;
 
    constructor(sudoku) {
        this.#started = false; 
        this.#history = [];
        this.#currentIndex = -1;
        this.#sudoku = new Sudoku(sudoku) || new Sudoku();
        this.saveHistory(); // 初始化时保存初始状态
    }

    get started() {
        return this.#started;
    }

    undo() {
        if (this.#currentIndex <= 0) return;
        this.#currentIndex--;
        this.#sudoku.fromJSON(this.#history[this.#currentIndex]);
    }

    redo() {
        if (this.#currentIndex >= this.#history.length - 1) return;
        this.#currentIndex++;
        const nextState = this.#history[this.#currentIndex];
        this.#sudoku.fromJSON(nextState);
    }

    saveHistory() {
        // 如果当前在撤销中间，新操作会清除未来的重做历史
        if (this.#currentIndex < this.#history.length - 1) {
            this.#history = this.#history.slice(0, this.#currentIndex + 1);
        }
        // 保存数独当前状态
        const state = this.#sudoku.toJSON();
        this.#history.push(state);
        this.#currentIndex = this.#history.length - 1;
    }

    getSudoku() {
        return this.#sudoku;
    }

    guess(move) {
        const success = this.#sudoku.guess(move);
        if (!success) return false;
        this.saveHistory();
        return true;
    }

    canUndo() {
        return this.#currentIndex > 0;
    }

    canRedo() {
        return this.#currentIndex < this.#history.length - 1;
    }

    toJSON() {
        return {
            sudoku: this.#sudoku.toJSON(),
            history: this.#history,
            currentIndex: this.#currentIndex
        };
    }
    

    static fromJSON(json) {
        const game = new Game();
        game.fromJSON(json);
        return game;
    }

    fromJSON(json) {
        if (!json || !json.sudoku || !json.sudoku.grid || !this.#sudoku.isValidGrid(json.sudoku.grid)) {
			throw new Error('Invalid JSON');
		}
        this.#sudoku.fromJSON(json.sudoku);
        this.#history = [...json.history];
        this.#currentIndex = json.currentIndex;
        this.#started = true;
    }
 isValidGameJSON(json) {
    if (typeof json !== 'object' || json === null) return false;
    if (!json.sudoku || !json.sudoku.grid) return false;
    if (!this.#sudoku.isValidGrid(json.sudoku.grid)) return false;
    if (!Array.isArray(json.history)) return false;
    if (typeof json.currentIndex !== 'number' || json.currentIndex < 0 || json.currentIndex >= json.history.length) return false;
    // 校验 history 里的每个快照
    for (const snap of json.history) {
        if (!snap.grid || !this.#sudoku.isValidGrid(snap.grid)) return false;
    }
    return true;
}
   numbers_to_select(pos){
    return this.#sudoku.numbers_to_select(pos);
   }
   next_step_hint(){
    return findNakedSingle(this.#sudoku)
        || findHiddenSingleInRow(this.#sudoku)
        || findHiddenSingleInColumn(this.#sudoku)
        || findHiddenSingleInBox(this.#sudoku)
        || null;
   }
}


  